{"implementation":"def solve(case):
    payload = case["payload"]
    attempts = payload["attempts"]
    max_attempts = payload["max_attempts"]
    if any(att["success"] for att in attempts):
        return {"decision": "success_terminate", "next_attempt_index": -1, "memory_update": None}
    signatures = [att["failure_signature"] for att in attempts]
    if len(signatures) != len(set(signatures)):
        return {"decision": "repeated_failure_terminate", "next_attempt_index": -1, "memory_update": None}
    if len(attempts) >= max_attempts:
        return {"decision": "budget_exhausted_terminate", "next_attempt_index": -1, "memory_update": None}
    last = attempts[-1] if attempts else None
    if attempts:
        mem = {"reflection": last["reflection"], "failure_signature": last["failure_signature"]}
    else:
        mem = {}
    return {"decision": "retry", "next_attempt_index": len(attempts), "memory_update": mem}"}
